/* ================================================================
 * GERAL — audio e ambiente do jogo
 * Arquivo original: js/audio-jogo.js
 * ================================================================ */
"use strict";
// Áudio comum às fases: cidade, passos nos canos e reação ao dano.
// Sons enviados pela equipe, coordenados com as fases sem alterar a música das notas.
(function (raiz) {
  const ambiente = new Audio("audio/cliffordjohnson-city-above-far-ambience-car-479129.mp3");
  const passos = new Audio("audio/som_passos.mp3");
  const dano = new Audio("audio/dano.mp3");
  ambiente.loop = true; passos.loop = true;
  ambiente.preload = "auto"; passos.preload = "auto"; dano.preload = "auto";
  passos.volume = 0.65;
  dano.volume = 0.38;
  let fase = "menu", som = true, pausado = false, movimento = false, desbloqueado = false, passosIniciando = false;

  // Interrompe um som e, quando pedido, retorna ao início do arquivo.
  function parar(audio, reiniciar = false) {
    audio.pause(); if (reiniciar && audio.readyState) audio.currentTime = 0;
  }

  // Só reproduz som depois da primeira interação e se o jogo estiver ativo.
  function tocar(audio) {
    if (!audio.paused || !desbloqueado || !som || pausado || document.hidden) return;
    audio.play().catch(() => {});
  }

  // Inicia os passos uma vez; evita criar várias reproduções simultâneas.
  function tocarPassos() {
    if (!passos.paused || passosIniciando || !desbloqueado || !som || pausado || document.hidden) return;
    passosIniciando = true;
    passos.play().catch(() => {}).finally(() => { passosIniciando = false; });
  }

  // Toca ambiente em todas as fases ativas e passos apenas ao andar na fase 01.
  function atualizar() {
    if (fase === "menu" || fase === "final" || !som || pausado || document.hidden) {
      parar(ambiente); parar(passos); return;
    }
    ambiente.volume = fase === "ondas" ? 0.24 : fase === "notas" ? 0.10 : 0.14;
    tocar(ambiente);
    if (movimento && fase === "ondas") tocarPassos();
    else parar(passos, true);
  }
  function desbloquear() { desbloqueado = true; atualizar(); }

  // Troca a fase de áudio sem manter sons da fase anterior.
  function ativar(novaFase, somInicial = som) {
    fase = novaFase; som = somInicial; pausado = false; movimento = false;
    atualizar();
  }
  function mover(ativo) { if (movimento === ativo) return; movimento = ativo; atualizar(); }
  function tocarDano() {
    if (!som || pausado || document.hidden) return;
    dano.currentTime=0;dano.play().catch(()=>{});
  }
  function pausar(ativo) { pausado = ativo; if (ativo) movimento = false; atualizar(); }

  // Liga ou desliga os efeitos conforme o botão Som.
  function definirSom(ligado) { som = ligado; atualizar();if(!ligado)dano.pause(); if (ligado) desbloquear(); }
  function pararTudo() { fase = "menu"; movimento = false; atualizar();dano.pause(); }
  document.addEventListener("pointerdown", desbloquear, {once:true});
  document.addEventListener("keydown", desbloquear, {once:true});
  window.addEventListener("blur", () => pausar(true));
  document.addEventListener("visibilitychange", atualizar);
  raiz.audioJogo = { ativar, mover, tocarDano, pausar, definirSom, desbloquear, pararTudo,
    get fase() { return fase; }, get somLigado() { return som; }, get movimento() { return movimento; } };
})(window);

;

