"use strict";
// Arte do Beat usada nas fases 01 e 02. Alterna sprites de caminhada, pulo e dano.
// Enquadra os seis desenhos de caminhada recebidos e preserva o PNG original parado.
(function (raiz) {
  const passos = Array.from({length:6}, (_, indice) => {
    const imagem = new Image(); imagem.src = "imgs/passo" + indice + ".png"; return imagem;
  });
  const passosDano = Array.from({length:6}, (_, indice) => {
    const imagem = new Image(); imagem.src = "imgs/passo" + indice + "_dano.png"; return imagem;
  });
  const pulando = new Image(), pulandoDano = new Image();
  pulando.src = "imgs/pulando.png"; pulandoDano.src = "imgs/pulando_dano.png";
  const costas = new Image(); costas.src = "imgs/bundinha.png";
  const original = new Image(); original.src = "imgs/beat.png";

  // Escolhe o sprite conforme movimento, pulo e dano; desenha na posição do canvas.
  function desenhar(ctx, {movendo=false, olhandoAcima=false, tempo=0, escala=1, noAr=false, dano=false} = {}) {
    const numero = Math.floor(tempo * 10) % passos.length;
    const passo = dano ? passosDano[numero] : passos[numero];
    if(noAr) {
      const imagem=dano?pulandoDano:pulando;
      if(imagem.complete&&imagem.naturalWidth)ctx.drawImage(imagem,175,4,124,232,-30*escala,-100*escala,60*escala,100*escala);
      return;
    }
    if (movendo && passo.complete && passo.naturalWidth) {
      ctx.drawImage(passo,175,4,124,232,-30*escala,-100*escala,60*escala,100*escala);
      // Os quadros 2, 3 e 4 do material recebido omitem a cabeça; complete com o quadro 0.
      const cabeca=dano?passosDano[0]:passos[0];
      if ([2,3,4].includes(numero) && cabeca.complete && cabeca.naturalWidth) {
        ctx.drawImage(cabeca,201,38,65,100,-18*escala,-85*escala,31*escala,43*escala);
      }
      return;
    }
    if (dano && passosDano[0].complete && passosDano[0].naturalWidth) {
      ctx.drawImage(passosDano[0],175,4,124,232,-30*escala,-100*escala,60*escala,100*escala);
      return;
    }
    if (olhandoAcima && costas.complete && costas.naturalWidth) {
      ctx.drawImage(costas,152,44,704,872,-39.75*escala,-100*escala,79.5*escala,100*escala);
    } else if (original.complete && original.naturalWidth) {
      ctx.drawImage(original,20,8,396,498,-39.75*escala,-100*escala,79.5*escala,100*escala);
    }
  }
  raiz.animacaoBeat = { desenhar, passos, costas, original };
})(window);

;

