/* ================================================================
 * FASE 01 — canos por onde Beat se desloca
 * Arquivo original: js/canos.js
 * ================================================================ */
"use strict";
// Fase 01: desenho dos 4 canos usando a geometria definida em logica-ondas.js.
// Arte das plataformas usa os mesmos segmentos da lógica, inclusive na passagem.
(function () {

  // Desenha apoios e tubulações em camadas; altura e colisão usam o mesmo traçado.
  function desenhar(ctx) {
    const canos=window.logicaOndas.canos,altura=window.logicaOndas.alturaCano;
    const pixel=(x,y,w,h,cor)=>{ctx.fillStyle=cor;ctx.fillRect(Math.round(x),Math.round(y),w,h);};
    // Conexões e suportes por trás dos canos horizontais.
    for(const [x,de,ate] of [[140,1,2],[320,0,1],[690,1,2],[855,0,2],[405,3,0],[740,3,0]]) {
      const top=altura(canos[de],x),bottom=altura(canos[ate],x)+25;
      pixel(x-7,top,16,bottom-top,"#080b13");pixel(x-3,top,7,bottom-top,"#43515a");
      for(let y=top+12;y<bottom;y+=36){pixel(x-10,y,22,7,"#1b2630");pixel(x-7,y,16,3,"#62717a");}
    }
    for(let id=0;id<canos.length;id++) {
      const cano=canos[id];
      for(let x=cano.x1;x<cano.x2;x+=8) {
        const y=Math.round(altura(cano,x)/2)*2;
        pixel(x,y-2,8,32,"#080b13");pixel(x,y,8,25,"#2c3b49");
        pixel(x,y,8,4,id===2?"#718075":id===3?"#9d798e":"#687481");pixel(x,y+5,8,3,"#4f5b62");
        pixel(x,y+19,8,6,"#172330");
        const n=Math.floor(x/8);
        if(n%13<3)pixel(x,y+8+(n%3)*2,8,4,"#725148");
        if(n%17===0)pixel(x,y+5,8,3,id===1?"#685063":"#405868");
      }
      for(let x=cano.x1+22;x<cano.x2;x+=84) {
        const y=altura(cano,x);
        pixel(x,y-4,11,36,"#080b13");pixel(x+2,y-2,7,32,"#50606a");
        pixel(x+3,y,5,4,"#84908b");pixel(x+3,y+8,3,4,"#181f29");pixel(x+3,y+23,3,4,"#181f29");
      }
    }
  }
  window.arteCanos={desenhar};
})();

