"use strict";
// Fase 01: síntese do som de vento emitido na passagem das ondas.
// Rajadas breves de vento para as ondas, sintetizadas sem arquivos extras.
(function (raiz) {
  let contexto, ruido;
  const ativos = new Set();

  // Cria uma rajada filtrada; limita a 3 sons simultâneos.
  function tocar() {
    const AudioContexto = window.AudioContext || window.webkitAudioContext;
    if (!AudioContexto || ativos.size >= 3) return;
    if (!contexto) contexto = new AudioContexto();
    if (contexto.state === "suspended") contexto.resume().catch(() => {});
    if (!ruido) {
      ruido = contexto.createBuffer(1, Math.ceil(contexto.sampleRate), contexto.sampleRate);
      const amostras = ruido.getChannelData(0);
      for (let i = 0; i < amostras.length; i++) amostras[i] = Math.random() * 2 - 1;
    }
    const agora = contexto.currentTime;
    const fonte = contexto.createBufferSource(), filtro = contexto.createBiquadFilter(), volume = contexto.createGain();
    fonte.buffer = ruido;
    filtro.type = "lowpass";
    filtro.frequency.setValueAtTime(1200, agora);
    filtro.frequency.exponentialRampToValueAtTime(360, agora + .7);
    volume.gain.setValueAtTime(.001, agora);
    volume.gain.linearRampToValueAtTime(.065, agora + .12);
    volume.gain.exponentialRampToValueAtTime(.001, agora + .7);
    fonte.connect(filtro); filtro.connect(volume); volume.connect(contexto.destination);
    fonte.onended = () => { ativos.delete(fonte); fonte.disconnect(); filtro.disconnect(); volume.disconnect(); };
    ativos.add(fonte); fonte.start(agora); fonte.stop(agora + .72);
  }

  // Para imediatamente todas as rajadas ao pausar ou trocar de fase.
  function parar() {
    for (const fonte of ativos) { try { fonte.stop(); } catch (_) {} }
    ativos.clear();
  }
  raiz.sonsOndas = { tocar, parar };
})(window);

