    ctx.fillStyle = "#f2faff";
    ctx.font = '600 20px "Chakra Petch"';
    ctx.fillText(`Acertos: ${percentualAcertos.toFixed(1)}%`, 480, 300);
    ctx.fillText(`Erros: ${percentualErros.toFixed(1)}%`, 480, 340);
