// Abre o seletor de gênero ou o conteúdo de Como jogar e Saiba mais.
async function abrirJanela(acao, botao) {
  if (janelaMenu.open || aguardandoJogar || jogo.telaAtual !== "inicio") return;
  if (acao === "jogar") {
    jogo.telaAtual = "escolher-genero";
    ultimoBotao = botao;
    ocultarMarcador();
    aguardandoJogar = true;
    cenario.src = "imgs/cenario-gustavo-on.jpg";
    await new Promise(resolve => setTimeout(resolve, 1000));
    if (jogo.telaAtual !== "escolher-genero") {
      aguardandoJogar = false;
      return;
    }
    aguardandoJogar = false;
    janelaGenero.showModal();
    janelaGenero.querySelector("[data-genero]").focus();
    return;
  }
  const tela = telasMenu[acao];
  if (!tela) return;

  jogo.telaAtual = acao;
  ultimoBotao = botao;
  tituloJanela.textContent = tela.titulo;
  textoJanela.innerHTML = tela.texto;
  janelaMenu.showModal();
  botaoVoltar.focus();
}

// Fecha o modal de informação e devolve o foco ao menu.
function fecharJanela() {
  janelaMenu.close();
}

botoesMenu.forEach((botao) => {
  botao.addEventListener("click", () => abrirJanela(botao.dataset.acao, botao));
});
botaoVoltar.addEventListener("click", fecharJanela);
janelaGenero.querySelectorAll("[data-genero]").forEach(botao => botao.addEventListener("click", () => {
  if (!janelaGenero.open || jogo.telaAtual !== "escolher-genero") return;
  window.musicaBeat.selecionar(botao.dataset.genero);
  jogo.telaAtual = "fase1";
  janelaGenero.close();
  window.faseOndas.iniciar();
}));
document.querySelector("#cancelar-genero").addEventListener("click", () => janelaGenero.close());
janelaGenero.addEventListener("close", () => {
  if (jogo.telaAtual !== "escolher-genero") return;
  jogo.telaAtual = "inicio";
  cenario.src = "imgs/cenario-gustavo.jpg";
  ultimoBotao?.focus();
});

janelaMenu.addEventListener("close", () => {
  jogo.telaAtual = "inicio";
  ultimoBotao?.focus();
});

// Fecha somente quando o clique acontece fora da área da janela.
janelaMenu.addEventListener("click", (evento) => {
  if (evento.target !== janelaMenu) return;
  const area = janelaMenu.getBoundingClientRect();
  const fora = evento.clientX < area.left || evento.clientX > area.right ||
    evento.clientY < area.top || evento.clientY > area.bottom;
  if (fora) fecharJanela();
});

// Setas percorrem o menu; Enter já funciona nativamente nos botões.
document.addEventListener("keydown", (evento) => {
  if (janelaMenu.open || jogo.telaAtual !== "inicio") return;
  if (evento.key === "ArrowDown" || evento.key === "ArrowUp") {
    evento.preventDefault();
    const atual = botoesMenu.indexOf(document.activeElement);
    const direcao = evento.key === "ArrowDown" ? 1 : -1;
    const proximo = atual < 0 ? (direcao === 1 ? 0 : botoesMenu.length - 1) :
      (atual + direcao + botoesMenu.length) % botoesMenu.length;
    botoesMenu[proximo].focus();
  }
});

window.addEventListener("voltar-menu", () => {
  aguardandoJogar = false;
  window.audioJogo.pararTudo();
  jogo.telaAtual = "inicio";
  cenario.src = "imgs/cenario-gustavo.jpg";
  ultimoBotao?.focus();
});

window.addEventListener("abrir-fase2", () => { jogo.telaAtual = "fase3"; });
window.addEventListener("abrir-transicao", () => { jogo.telaAtual = "transicao"; });

window.addEventListener("abrir-ondas", () => { jogo.telaAtual = "fase1"; });
window.addEventListener("abrir-notas", () => { jogo.telaAtual = "fase2"; });
window.addEventListener("abrir-show", () => { jogo.telaAtual = "fase4"; });
window.addEventListener("abrir-final", () => { jogo.telaAtual = "final"; });

;
